//! 🧭️ The real native slot retains its action across a recorded Source Post unwind.
use semio_framework_value_control_contract::*;
use semio_framework_value_native_decoding::*;
use semio_framework_value_native_owned::{DslValue,owned::tree::NativeReceiveSlot,retained_clone::RetainedCloneSource};
use semio_framework_value_retirement::{OriginalRetirementCloseLoan,OriginalRetirementFailure};
#[path="../../../🏭️construction/🧪️tests/source-bank.rs"]mod source_bank;
use source_bank::Bank;
use semio_framework_value_clone_source_testing::FixtureSourceBirth;
type Slot=NativeReceiveSlot<DslValue,String>;
struct Close;
impl OriginalEffectProducer for Close{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut Slot,bool,Option<&'a mut OriginalRetirementCloseLoan<'b>>)where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{if c.1{return c.0.begin_close_into(effect,reply)}match c.2.as_deref_mut(){Some(loan)=>c.0.close_original_into(loan,4096,effect,reply),None=>c.0.close_into(4096,effect,reply)}}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{if c.1{return c.0.recover_begin_close_into(effect,reply)}match c.2.as_deref_mut(){Some(loan)=>c.0.recover_close_original_into(loan,4096,effect,reply),None=>c.0.recover_close_into(4096,effect,reply)}}}
struct Ack;
impl OriginalEffectProducer for Ack{type Output=RetainedCloneStep;type Failure=ValueError;type Context<'a,'b>=(&'a mut NativeReceivingEffect<OriginalRetirementFailure>,&'a mut Option<RetainedCloneStep>)where 'b:'a;fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{c.0.acknowledge_resident_success_into(c.1,effect,reply)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.receive(c,effect,reply)}}
fn settle(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>){let d=frame.resident_success_ack_demand().unwrap();let mut meta=NativeReceivingEffect::<ValueError>::default();let mut owner=OriginalEffectAuthority::new(Ack);let mut output=None;match bank.run(native,|control|control.receive_original_effect(d,1,&mut meta,&mut owner,|_,effect,p,action|p.drive(&mut (frame,&mut output),effect,action))).unwrap(){NativeReceivingEffectPoll::Complete(turn)=>{turn.result.unwrap();},_=>panic!("native parent ack pending")};assert!(output.is_some());assert!(owner.into_producer().is_ok());}
#[test]fn original_slot_blocks_close_until_recorded_post_settles(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🔗️sealed-shared-receiver/🧪️tests/source-bank.json")).unwrap();let mut bank=Bank::from_stock(&law["stock"],false);let mut source=RetainedCloneSource::<DslValue>::from_owner(DslValue::Null);let input=source.borrow();let identity=input.reference_identity();let mut slot=Slot::default();let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut native=NativeDecodeControl::new(65536,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};bank.interrupt_copy.store(true,std::sync::atomic::Ordering::SeqCst);let first=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run_with_turn(&mut native,|turn,control|Ok(slot.advance(input,control,turn.witness(),4096,16,grant)))));assert!(first.is_err());assert!(slot.advance_pending());assert_eq!(slot.begin_close_demand().is_ok(),law["parentCloseBeforePost"].as_bool().unwrap());assert_eq!(input.reference_identity(),identity);let resumed=bank.run_with_turn(&mut native,|turn,control|Ok(slot.advance(input,control,turn.witness(),4096,16,grant))).unwrap();if let RetainedWorkPoll::Complete(turn)=resumed{turn.result.unwrap();}assert!(!slot.advance_pending());let mut frame=NativeReceivingEffect::<OriginalRetirementFailure>::default();let mut close=OriginalEffectAuthority::new(Close);let d=slot.begin_close_demand().unwrap();assert!(matches!(bank.run(&mut native,|control|control.receive_original_effect_retained(d,1,&mut frame,&mut close,&mut (&mut slot,true,None))).unwrap(),NativeReceivingEffectState::Ready{..}));settle(&mut bank,&mut native,&mut frame);for _ in 0..law["maximumTurns"].as_u64().unwrap(){if slot.terminal_is_empty(){break}if slot.requires_original_birth(){let turn=bank.run(&mut native,|control|control.with_retirement(grant,|funding|funding.with_original_close(|loan|Ok(slot.close_original_birth_step(loan,grant))))).unwrap();if let RetainedWorkPoll::Complete(turn)=turn{turn.result.unwrap();}continue}let d=slot.close_demands(4096).unwrap();let work=slot.close_work_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let state=if slot.requires_original_control(){bank.run(&mut native,|control|control.receive_original_effect_retained_with(d,work,&mut frame,&mut close,|control,effect,owner,action|control.with_retirement(effect.grant(),|funding|funding.with_original_close(|loan|owner.drive(&mut (&mut slot,false,Some(loan)),effect,action))))).unwrap()}else{bank.run(&mut native,|control|control.receive_original_effect_retained(d,work,&mut frame,&mut close,&mut (&mut slot,false,None))).unwrap()};if matches!(state,NativeReceivingEffectState::Ready{..}){settle(&mut bank,&mut native,&mut frame)}}assert!(slot.terminal_is_empty());assert!(close.into_producer().is_ok());drop(slot);assert_eq!(u128::from(law["stock"]["fuel"].as_u64().unwrap())-bank.wallet.lock().unwrap().fuel,native.actual_work());for _ in 0..law["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty(){break}source.close_once().unwrap();}assert!(source.terminal_is_empty());}
